        let genesis_hash = hex::encode(h.finalize().as_bytes());
        let expected_trace = format!("trace-{}", genesis_hash);

        assert!(expected_trace.starts_with("trace-"));
        assert_eq!(expected_trace.len(), 6 + 64); // "trace-" + 64 hex chars
    }

