}

export function parseGeneratedSpec(text: string): { spec: Spec; generated: GenerateUi } {
  const parsed = extractJsonObject(text);
  const generated = GenerateUiSchema.parse(parsed);
  return { spec: toFlatSpec(generated), generated };
}

